          "text": "Passage: 'The Bengal tiger, India's national animal, is classified as endangered. Conservation efforts under Project Tiger have led to an increase in tiger population from 1,411 in 2006 to 3,167 in 2022. However, habitat fragmentation and poaching remain persistent threats, particularly in corridors connecting tiger reserves.' The tone of the passage can best be described as:",
