          "id": 615,
          "text": "Passage: 'The phenomenon of 'brain drain' — the emigration of highly skilled workers — has historically been viewed as a loss for developing countries. Recent research, however, suggests that diaspora networks can facilitate trade, investment, and knowledge transfer back to the home country, turning 'brain drain' into 'brain gain'.' What does the passage suggest about brain drain?",
