          "text": "Passage: 'The Indus Valley Civilisation, one of the world's oldest urban civilisations, flourished around 2500 BCE in what is now Pakistan and northwest India. The cities of Harappa and Mohenjo-Daro featured advanced drainage systems, grid-planned streets, and uniform brick sizes — indicating a high degree of urban planning.' What does the uniform brick size suggest about the Indus Valley Civilisation?",
