          "text": "Select the word that best completes the sentence: 'If the monsoon onset had been delayed by three weeks, the resulting drought would have triggered a scenario described as a ______,' where the blank requires a term for a situation of sudden, overwhelming scarcity caused specifically by a lack of rain during the critical agricultural window.'",
