          "solution": "The context describes a 'soft-lending' policy which implies low costs for the borrower. The sentence structure 'avoid any practice that...' requires a word meaning 'to take unfair advantage of someone's weakness or situation for profit'. Among the options, only 'Exploit' fits this negative definition (charging exorbitant fees/hidden costs), making it the correct antonym to the supportive policy described.",
