          "solution": "1. Analyze the context: A sudden financial collapse or withdrawal of investment.\n2. Evaluate Option A ('blew up'): Means an explosion or angry outburst; implies destruction but not retreat.\n3. Evaluate Option C ('hit bottom'): Refers to a low point in value, not a departure.\n4. Evaluate Option D ('turned sour'): Refers to deteriorating quality or attitude, not leaving.\n5. Evaluate Option B ('folded its tents'): Originating from travelers setting up camp and packing away tents to leave quickly; metaphorically means to retreat or withdraw suddenly.\n6. Conclusion: 'Folded its tents' fits the context of investors withdrawing their capital abruptly.",
