          "text": "In a frantic rush to fix the broken bridge before the monsoon, the village engineer shouted at the contractors, 'Stop! You are trying to ___________ by using these temporary bamboo poles!' He believed they were attempting to make the river flow through a solid wall of wood.\nWhich idiom best completes the engineer's frustrated outburst?\nA. paint the town red\nB. build castles in the air\nC. count chickens before they hatch\nD. throw good money after bad",
