          "text": "Choose the most appropriate sentence that improves the one given below.\nOriginal: 'The stock market crash was a real eye-waterer for the traders.'\nA. The stock market crash was a real eye-opener for the traders.\nB. The stock market crash was a real heart-breaker for the traders.\nC. The stock market crash was a real tear-jerker for the traders.\nD. The stock market crash was a real eye-waterer for the traders.",
