          "text": "A 'Rashtriya Karmayogi' portal has launched to digitise the administration. During the inauguration, the Prime Minister noted that 'bureaucratic delays are often caused by a lack of __________ in decision-making'. Which word best completes the sentence while maintaining formal administrative register?",
